# Load all grids from the session history to track what we've received
import os, glob, re, json, copy

RLM_SESSION_DIR = os.environ['RLM_SESSION_DIR']
session_folder = os.path.normpath(os.path.join(RLM_SESSION_DIR, '../../sessions'))
session_name = os.path.basename(os.path.normpath(RLM_SESSION_DIR))
session_file = os.path.join(session_folder, session_name + '.jsonl')

def load_grids():
    G = {}
    if not os.path.exists(session_file):
        return G
    with open(session_file) as f:
        content = f.read().replace('\\n', '\n')

    for msg in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = msg[1], int(msg[2]), int(msg[3])
        rows_start = msg.end()
        rows_str = content[rows_start:].split('\n')[:h]
        if rows_start in content and k not in G:
            rows_valid = True
            rows_data = []
            for r in rows_str:
                if r.strip():
                    row_vals = [x for x in r.split() if x.isdigit()]
                    if len(row_vals) != w:
                        rows_valid = False
                        break
                    rows_data.append([int(x) for x in row_vals])
            if rows_valid:
                G[k] = rows_data

    return G

G = load_grids()
print("Loaded grids (dict keys):", list(G.keys()))
print()
for key in sorted(G.keys() if isinstance(G, dict) else []):
    if key in G:
        print(f"=== {key}: {len(G[key])}x{len(G[key][0]) if G[key] else 0} ===")
        for i, row in enumerate(G[key][:3]):  # show first 3 rows
            print(f"  Row {i}: {row}")
        if len(G[key]) > 3:
            print(f"  ... ({len(G[key])} rows total)")
        if key == 'Test input':
            print(f"[TEST INPUT]")
        if 'input' in key.lower():
            print(f"[INPUT PAIR]")
        if 'output' in key.lower():
            print(f"[OUTPUT PAIR]")

